/**
 * Clone validation runner.
 *
 * Drives a real source API through a create / update / delete / UN-DELETE
 * lifecycle and asserts what landed in the MySQL clone after each sync.
 *
 *   node validate.js 4x    source: meadow-endpoints 4.x  (PostgreSQL or MSSQL)
 *   node validate.js 2x    source: meadow-endpoints 2.1.1 (MySQL)
 *
 * Prints [ok]/[fail] per invariant and exits non-zero if any failed.
 */
const libFS = require('fs');
const libPath = require('path');
const libMySQL2 = require('mysql2/promise');

const libFable = require('fable');
const libMeadowConnectionManager = require('meadow-integration/source/services/clone/Meadow-Service-ConnectionManager.js');
const libMeadowCloneRestClient = require('meadow-integration/source/services/clone/Meadow-Service-RestClient.js');
const libMeadowSync = require('meadow-integration/source/services/clone/Meadow-Service-Sync.js');

const _Model = require('../shared/Model-Book.json');

const LEG = (process.argv[2] || '4x').toLowerCase();
// Which store sits behind the 4.x source API; must match the source container.
const SOURCE_ENGINE = (process.env.SOURCE_ENGINE || 'postgres').toLowerCase();

const _MySQLConfig =
{
	host: process.env.MYSQL_HOST || 'mysql',
	port: parseInt(process.env.MYSQL_PORT, 10) || 3306,
	user: process.env.MYSQL_USER || 'root',
	password: process.env.MYSQL_PASSWORD || '',
	namedPlaceholders: true
};

const _Legs =
{
	'4x':
	{
		Label: 'meadow-endpoints 4.x source',
		SourceURL: process.env.SOURCE_4X_URL || 'http://source-4x:8086/1.0/',
		CloneDatabase: 'clone4x',
		// The 4.x source exposes a real un-delete endpoint.
		UndeleteMode: 'endpoint',
		// The clone's delete phase does not need the legacy workaround here.
		SyncDeletedRecordsQueryString: ''
	},
	'2x':
	{
		Label: 'meadow-endpoints 2.1.1 source',
		SourceURL: process.env.SOURCE_2X_URL || 'http://source-2x:8086/1.0/',
		CloneDatabase: 'clone2x',
		// meadow-endpoints 2.x has no un-delete route, and PUT cannot clear the
		// flag (its pre-update read is delete-tracked), so the record is restored
		// in the source store the way an operator would have to do it today.
		UndeleteMode: 'sql',
		SourceDatabase: process.env.SOURCE_2X_MYSQL_DATABASE || 'source2x',
		// Headlight's 2.x API needs this to expose its deleted set; harmless on
		// stock meadow-endpoints, and carrying it proves it stays harmless.
		SyncDeletedRecordsQueryString: 'includeDeleted=true'
	}
};

const _Leg = _Legs[LEG];
if (!_Leg)
{
	console.error(`Unknown leg [${LEG}]; expected 4x or 2x.`);
	process.exit(1);
}

let _Failures = 0;
let _Checks = 0;

const check = (pLabel, pCondition, pDetail) =>
{
	_Checks++;
	if (pCondition)
	{
		console.log(`  [ok]   ${pLabel}`);
	}
	else
	{
		_Failures++;
		console.log(`  [fail] ${pLabel}${pDetail ? ` — ${pDetail}` : ''}`);
	}
};

const section = (pTitle) => { console.log(`\n== ${pTitle}`); };

// ── Source API ──────────────────────────────────────────────────────────────

const sourceCall = async (pMethod, pPath, pBody) =>
{
	const tmpOptions = { method: pMethod, headers: { 'Content-Type': 'application/json' } };
	if (pBody)
	{
		tmpOptions.body = JSON.stringify(pBody);
	}
	const tmpResponse = await fetch(`${_Leg.SourceURL}${pPath}`, tmpOptions);
	const tmpText = await tmpResponse.text();
	try
	{
		return JSON.parse(tmpText);
	}
	catch (pParseError)
	{
		return tmpText;
	}
};

const waitForSource = async () =>
{
	for (let i = 0; i < 60; i++)
	{
		try
		{
			const tmpResult = await sourceCall('GET', 'Books/Count');
			if (tmpResult && tmpResult.hasOwnProperty('Count'))
			{
				return;
			}
		}
		catch (pError)
		{
			// not up yet
		}
		await new Promise((fResolve) => { return setTimeout(fResolve, 2000); });
	}
	throw new Error(`Source API at ${_Leg.SourceURL} never became ready.`);
};

// ── Source store (direct, for reset and the 2.x un-delete) ──────────────────

const withSourceStore = async (fAction) =>
{
	if (LEG === '2x')
	{
		const tmpConnection = await libMySQL2.createConnection(Object.assign({}, _MySQLConfig, { database: _Leg.SourceDatabase }));
		try
		{
			return await fAction(
				{
					query: async (pSQL, pParams) => { const [tmpRows] = await tmpConnection.query(pSQL, pParams || []); return tmpRows; }
				});
		}
		finally
		{
			await tmpConnection.end();
		}
	}

	if (SOURCE_ENGINE === 'mssql')
	{
		const libMSSQL = require('mssql');
		const tmpPool = await libMSSQL.connect(
			{
				server: process.env.MSSQL_HOST || 'mssql',
				port: parseInt(process.env.MSSQL_PORT, 10) || 1433,
				user: process.env.MSSQL_USER || 'sa',
				password: process.env.MSSQL_PASSWORD || '',
				database: process.env.MSSQL_DATABASE || 'source4x',
				options: { trustServerCertificate: true, encrypt: false }
			});
		try
		{
			return await fAction(
				{
					query: async (pSQL) => { const tmpResult = await tmpPool.request().query(pSQL); return tmpResult.recordset; }
				});
		}
		finally
		{
			await tmpPool.close();
		}
	}

	const libPG = require('pg');
	const tmpClient = new libPG.Client(
		{
			host: process.env.POSTGRES_HOST || 'postgres',
			port: parseInt(process.env.POSTGRES_PORT, 10) || 5432,
			user: process.env.POSTGRES_USER || 'postgres',
			password: process.env.POSTGRES_PASSWORD || '',
			database: process.env.POSTGRES_DATABASE || 'source4x'
		});
	await tmpClient.connect();
	try
	{
		return await fAction(
			{
				query: async (pSQL, pParams) => { const tmpResult = await tmpClient.query(pSQL, pParams || []); return tmpResult.rows; }
			});
	}
	finally
	{
		await tmpClient.end();
	}
};

const resetSource = async () =>
{
	await withSourceStore(async (pStore) =>
	{
		if (LEG === '2x')
		{
			await pStore.query('TRUNCATE TABLE Book');
		}
		else if (SOURCE_ENGINE === 'mssql')
		{
			// TRUNCATE reseeds the identity on MSSQL, so ids restart at 1 as they
			// do on the other engines.
			await pStore.query('TRUNCATE TABLE [Book]');
		}
		else
		{
			await pStore.query('TRUNCATE TABLE "Book" RESTART IDENTITY');
		}
	});
};

const undeleteAtSource = async (pID) =>
{
	if (_Leg.UndeleteMode === 'endpoint')
	{
		return sourceCall('GET', `Book/Undelete/${pID}`);
	}

	return withSourceStore(async (pStore) =>
	{
		return pStore.query('UPDATE Book SET Deleted = 0, UpdateDate = NOW() WHERE IDBook = ?', [ pID ]);
	});
};

// ── Clone database ──────────────────────────────────────────────────────────

const withClone = async (fAction) =>
{
	const tmpConnection = await libMySQL2.createConnection(Object.assign({}, _MySQLConfig, { database: _Leg.CloneDatabase }));
	try
	{
		return await fAction(tmpConnection);
	}
	finally
	{
		await tmpConnection.end();
	}
};

const resetClone = async () =>
{
	await withClone(async (pConnection) => { await pConnection.query('DROP TABLE IF EXISTS Book'); });
};

const cloneRows = async () =>
{
	return withClone(async (pConnection) =>
	{
		const [ tmpRows ] = await pConnection.query('SELECT * FROM Book ORDER BY IDBook');
		return tmpRows;
	});
};

const cloneRowByID = async (pID) =>
{
	const tmpRows = await cloneRows();
	return tmpRows.find((pRow) => { return Number(pRow.IDBook) === Number(pID); });
};

// ── The clone under test ────────────────────────────────────────────────────

/**
 * Run one full sync pass, wired the way a scheduled clone run is wired.
 */
let _SyncPass = 0;

const runSync = () =>
{
	return new Promise((fResolve, fReject) =>
	{
		// Sync logs are captured so the scenario can assert on HOW the clone
		// reconciled a record, not just where it ended up.  On MySQL a failed
		// identity insert is recoverable, so an un-delete that limps through the
		// duplicate-key fallback still lands correctly — the log is what tells
		// the two paths apart.
		// Scoped to this process: the flat-file logger appends, so a fixed name
		// would let a previous run's lines leak into this run's assertions.
		const tmpLogPath = libPath.join(require('os').tmpdir(), `clone-sync-${LEG}-${process.pid}-${++_SyncPass}.log`);

		const tmpFable = new libFable(
			{
				Product: `CloneHarness-${LEG}`,
				ProductVersion: '1.0.0',
				LogStreams:
					[
						{ streamtype: 'console', level: 'error' },
						{ loggertype: 'simpleflatfile', outputloglinestoconsole: false, level: 'trace', path: tmpLogPath }
					]
			});
		tmpFable.SyncLogPath = tmpLogPath;
		tmpFable.ProgramConfiguration = {};
		if (_Leg.SyncDeletedRecordsQueryString)
		{
			tmpFable.ProgramConfiguration.SyncDeletedRecordsQueryString = _Leg.SyncDeletedRecordsQueryString;
		}

		tmpFable.serviceManager.addServiceType('MeadowConnectionManager', libMeadowConnectionManager);
		const tmpConnectionManager = tmpFable.serviceManager.instantiateServiceProvider('MeadowConnectionManager',
			{
				Provider: 'MySQL',
				MySQL:
					{
						server: _MySQLConfig.host,
						port: _MySQLConfig.port,
						user: _MySQLConfig.user,
						password: _MySQLConfig.password,
						database: _Leg.CloneDatabase,
						connectionLimit: 5
					}
			});

		tmpConnectionManager.connect(
			(pConnectError, pConnectionPool) =>
			{
				if (pConnectError)
				{
					return fReject(pConnectError);
				}

				tmpFable.serviceManager.addServiceType('MeadowCloneRestClient', libMeadowCloneRestClient);
				tmpFable.serviceManager.instantiateServiceProvider('MeadowCloneRestClient', { ServerURL: _Leg.SourceURL });

				tmpFable.serviceManager.addServiceType('MeadowSync', libMeadowSync);
				tmpFable.serviceManager.instantiateServiceProvider('MeadowSync',
					{
						PageSize: 100,
						SyncDeletedRecords: true,
						BackSyncTimeLimit: 60000,
						ConnectionPool: pConnectionPool
					});
				tmpFable.MeadowSync.SyncMode = 'OngoingEventualConsistency';
				tmpFable.MeadowSync.SyncDeletedRecords = true;
				tmpFable.MeadowSync.BackSyncTimeLimit = 60000;

				tmpFable.MeadowSync.loadMeadowSchema({ Tables: { Book: _Model.Tables.Book } },
					(pSchemaError) =>
					{
						if (pSchemaError)
						{
							return fReject(pSchemaError);
						}

						const tmpEntity = tmpFable.MeadowSync.MeadowSyncEntities['Book'];
						tmpEntity.sync(
							() =>
							{
								const tmpResults = tmpEntity.syncResults || {};
								const fFinish = () =>
								{
									let tmpLogText = '';
									try
									{
										tmpLogText = libFS.readFileSync(tmpLogPath, 'utf8');
									}
									catch (pLogError)
									{
										tmpLogText = '';
									}
									try
									{
										libFS.unlinkSync(tmpLogPath);
									}
									catch (pCleanupError)
									{
										// nothing to clean up
									}
									return fResolve({ Results: tmpResults, Log: tmpLogText });
								};

								if (tmpFable.MeadowMySQLProvider && tmpFable.MeadowMySQLProvider.pool)
								{
									tmpFable.MeadowMySQLProvider.pool.end(fFinish);
									return;
								}
								return fFinish();
							});
					});
			});
	});
};

// ── Scenario ────────────────────────────────────────────────────────────────

const seedBook = (pID, pTitle) =>
{
	return sourceCall('POST', 'Book', { Title: pTitle, GUIDBook: `GUID-BOOK-${pID}` });
};

/**
 * An edit that changes no record counts is detected by comparing UpdateDate
 * across the two databases, and that comparison allows DateTimePrecisionMS
 * (1s by default) of slop for engines that truncate timestamps.  Real edits
 * arrive long after the rows were cloned; this scenario would otherwise make
 * them in the same second, inside the tolerance.  MySQL DATETIME truncates to
 * whole seconds, so the gap has to clear two ticks, not one.
 */
const spaceBeyondTimestampTolerance = () =>
{
	return new Promise((fResolve) => { return setTimeout(fResolve, 2500); });
};

const run = async () =>
{
	console.log(`\n#### Clone validation — ${_Leg.Label}`);
	console.log(`     source ${_Leg.SourceURL}  ->  clone mysql/${_Leg.CloneDatabase}`);

	section('Harness integrity');
	const tmpSyncSource = libFS.readFileSync(
		libPath.join(require.resolve('meadow-integration/source/services/clone/Meadow-Service-Sync-Entity-Ongoing.js')), 'utf8');
	const tmpUpsertBody = tmpSyncSource.slice(
		tmpSyncSource.indexOf('_upsertRecord(pServerRecord, fCallback)'),
		tmpSyncSource.indexOf('_pullServerRecords(pFilter'));
	check('clone image is running the local working-tree meadow-integration',
		tmpUpsertBody.length > 0 && tmpUpsertBody.indexOf('if (!this._hasDeletedColumn)') === -1,
		'the installed package still has the delete-tracked existence check in _upsertRecord — the image was not patched');

	await waitForSource();
	await resetSource();
	await resetClone();

	// ---- Initial sync -------------------------------------------------------
	section('Initial sync (base behavior)');
	for (let i = 1; i <= 5; i++)
	{
		await seedBook(i, `Book-${i}`);
	}
	await runSync();

	let tmpRows = await cloneRows();
	check('all five source records cloned', tmpRows.length === 5, `clone holds ${tmpRows.length}`);
	check('titles match the source', tmpRows.every((pRow, pIndex) => { return pRow.Title === `Book-${pIndex + 1}`; }));
	check('identities preserved across the clone boundary', tmpRows.map((pRow) => { return Number(pRow.IDBook); }).join(',') === '1,2,3,4,5');
	check('no records flagged deleted', tmpRows.every((pRow) => { return Number(pRow.Deleted) === 0; }));

	// ---- Create + update ----------------------------------------------------
	section('New and modified records (base behavior)');
	await seedBook(6, 'Book-6-New');
	await spaceBeyondTimestampTolerance();
	await sourceCall('PUT', 'Book', { IDBook: 1, Title: 'Book-1-EditedAtSource' });
	await runSync();

	tmpRows = await cloneRows();
	check('new source record cloned', tmpRows.length === 6, `clone holds ${tmpRows.length}`);
	const tmpBook6 = await cloneRowByID(6);
	check('new record has its source title', tmpBook6 && tmpBook6.Title === 'Book-6-New');
	const tmpBook1 = await cloneRowByID(1);
	check('edited record updated in the clone', tmpBook1 && tmpBook1.Title === 'Book-1-EditedAtSource', tmpBook1 && tmpBook1.Title);

	// ---- Delete -------------------------------------------------------------
	section('Source deletion (base behavior)');
	await sourceCall('DELETE', 'Book/3');
	await runSync();

	const tmpDeleted3 = await cloneRowByID(3);
	check('deleted record flagged in the clone', tmpDeleted3 && Number(tmpDeleted3.Deleted) === 1);
	check('deleted record kept, not removed', !!tmpDeleted3);
	check('unrelated records untouched', (await cloneRowByID(2)) && Number((await cloneRowByID(2)).Deleted) === 0);

	// ---- UN-DELETE ----------------------------------------------------------
	section('Source UN-DELETE (the behavior under test)');
	await undeleteAtSource(3);
	await sourceCall('PUT', 'Book', { IDBook: 3, Title: 'Book-3-RestoredAtSource' });

	const tmpSourceLive = await sourceCall('GET', 'Books/Count');
	check('source serves the restored record again', tmpSourceLive && tmpSourceLive.Count === 6, `source live count ${tmpSourceLive && tmpSourceLive.Count}`);

	const tmpUndeleteSync = await runSync();

	const tmpRestored = await cloneRowByID(3);
	check('restored record is live again in the clone', tmpRestored && Number(tmpRestored.Deleted) === 0,
		tmpRestored ? `Deleted=${tmpRestored.Deleted}` : 'row missing');
	check('restored record kept its GUID', tmpRestored && tmpRestored.GUIDBook === 'GUID-BOOK-3',
		tmpRestored && tmpRestored.GUIDBook);
	check('restored record caught up with the source', tmpRestored && tmpRestored.Title === 'Book-3-RestoredAtSource',
		tmpRestored && tmpRestored.Title);

	tmpRows = await cloneRows();
	check('no duplicate row created for the restored record', tmpRows.length === 6, `clone holds ${tmpRows.length}`);
	check('no GUID was collision-renamed', tmpRows.every((pRow) => { return String(pRow.GUIDBook).indexOf('__mdsd_') !== 0; }),
		tmpRows.map((pRow) => { return pRow.GUIDBook; }).join(' '));

	// The record is restored by updating the row that is already there.  Landing
	// it through a failed identity insert instead is what the delete-tracked
	// existence check used to do: recoverable on MySQL, silently lost on SQLite.
	check('restore was a plain update, not a recovered insert collision',
		tmpUndeleteSync.Log.indexOf('Duplicate key on create') === -1 && tmpUndeleteSync.Log.indexOf('Error creating record') === -1,
		'the sync fell back to the duplicate-key recovery path');

	// ---- Idempotency --------------------------------------------------------
	section('Repeat sync (no churn)');
	await runSync();
	const tmpAfterRepeat = await cloneRowByID(3);
	check('restored record stays live', tmpAfterRepeat && Number(tmpAfterRepeat.Deleted) === 0);
	check('row count stable', (await cloneRows()).length === 6);

	// ---- Delete again -------------------------------------------------------
	section('Delete after restore (round trip)');
	await sourceCall('DELETE', 'Book/3');
	await runSync();
	const tmpRedeleted = await cloneRowByID(3);
	check('record can be deleted again after being restored', tmpRedeleted && Number(tmpRedeleted.Deleted) === 1);

	await undeleteAtSource(3);
	await runSync();
	const tmpRerestored = await cloneRowByID(3);
	check('and restored again', tmpRerestored && Number(tmpRerestored.Deleted) === 0);

	// ---- Deleted before it was ever synced ----------------------------------
	section('Record deleted before it was ever cloned (base behavior)');
	const tmpNever = await seedBook(7, 'Book-7-DeletedBeforeSync');
	await sourceCall('DELETE', `Book/${tmpNever.IDBook}`);
	await runSync();

	check('never-synced deleted record is not backfilled', !(await cloneRowByID(tmpNever.IDBook)));
	check('clone row count unchanged', (await cloneRows()).length === 6, `clone holds ${(await cloneRows()).length}`);

	console.log(`\n---- ${_Checks - _Failures}/${_Checks} checks passed for the ${_Leg.Label}.`);
	return _Failures;
};

run()
	.then((pFailures) => { process.exit(pFailures > 0 ? 1 : 0); })
	.catch((pError) =>
	{
		console.error(`\nHarness error: ${pError && pError.stack ? pError.stack : pError}`);
		process.exit(1);
	});
